#!/usr/bin/env python3
"""Validate Bible annotations and unchanged frozen commentary pages.

Records must use the TEV/INC namespace, match source traditions, resolve every
locator, and name an exact paragraph anchor. Outputs use the Bible-owned index.
"""
from __future__ import annotations

import argparse
from contextlib import closing
import json
import re
import sys
from collections import Counter
from pathlib import Path

V2 = Path(__file__).resolve().parent
sys.path.insert(0, str(V2.parents[1]))
from enrichment.bible import blocks as B, corpus as C
from enrichment.bible import render as R

# the commentary called "taban" (taban, tabanın, tabandaki, tabana, tabanda …), not "ayak tabanı"/"dağın tabanında"
TABAN = re.compile(r"\btaban(?:ın|ı|a|da|daki|dan)?\b", re.IGNORECASE)
TABAN_OK = re.compile(r"\b(?:ayak|dağın|dağ|kabın|vadinin)\s+taban", re.IGNORECASE)


def check_page(page: Path, base: str, recs: list[dict]) -> list[str]:
    e = []
    text = page.read_text(encoding="utf-8")
    cursor = 0
    for n, p in enumerate(R.paragraphs(base), 1):
        i = text.find(p, cursor)
        if i < 0:
            e.append(f"{page.name}: base paragraph {n} missing or changed: {p[:80]!r}")
        else:
            cursor = i + len(p)
    by_id = {r["id"]: r for r in recs}
    found = Counter()
    reg = text.find("\n## Kaynak kayıtları")
    for line in text.splitlines():
        if line.startswith("{id:"):
            try:
                f = B.parse_line(line)
            except ValueError as x:
                e.append(f"{page.name}: unparsable block line: {x}")
                continue
            r = by_id.get(f.get("id"))
            found[f.get('id')] += 1
            if not r:
                e.append(f"{page.name}: block {f.get('id')} not in annotations")
            elif any(str(r.get(k)) != str(v) for k, v in f.items()):
                e.append(f"{page.name}: block {f['id']} does not round-trip")
            if reg >= 0 and text.find(line) > reg:
                e.append(f"{page.name}: block {f.get('id')} after the registry")
    if found != Counter(r['id'] for r in recs):
        e.append(f'{page.name}: missing or duplicate annotation blocks')
    return e


def check_records(s: int, target: str, recs: list[dict], gelenek: str = "ehlikitap") -> tuple[list[dict], list[dict], list[str]]:
    """(kept records, dropped [{id, errors}], warnings) for one page. gelenek: the pass ("islami") or "ehlikitap"
    for the Bible pass, whose records carry tevrat or incil themselves."""
    pk = V2 / "work" / f"s{s:03d}" / "pack"
    n_ayat = json.loads((pk / "pack.json").read_text(encoding="utf-8"))["ayat"]
    name, base, _ = R.target_page(s, target)
    paras = R.paragraphs(base)
    with closing(B.Corpus(C.INDEX)) as corpus:
        kept, dropped, warnings, seen = [], [], [], set()
        novelty_at: dict[str, str] = {}
        per_para: dict[str, int] = {}
        for r in recs:
            rid = r.get("id", "?")
            if gelenek == "islami":
                r.setdefault("gelenek", "islami")
            e = B.check_record(r, s, n_ayat, corpus, base)
            if gelenek == "islami" and r.get("gelenek") != "islami":
                e.append(f"{rid}: the Islamic pass writes only gelenek:islami")
            if gelenek == "ehlikitap" and r.get("gelenek") not in ("tevrat", "incil"):
                e.append(f"{rid}: the Bible pass writes gelenek tevrat or incil")
            if target != "surah":
                a = int(target.split(":")[1])
                try:
                    if not any(x[1] <= a <= x[2] for x in B.ayah_refs(r.get("ayet", ""))):
                        e.append(f"{rid}: ayet {r.get('ayet')} does not cover the page's ayah {target}")
                except ValueError:
                    pass  # reported by check_record
            if not str(r.get("paragraf", "")).strip() or not r.get("capa"):
                e.append(f"{rid}: paragraf and capa are required (every block goes after a paragraph of the base)")
            else:
                i, err = R.locate(paras, r)
                if i is None:
                    e.append(f"{rid}: {name}: {err}")
            if rid in seen:
                e.append(f"{rid}: duplicate id")
            try:  # the same number placement uses (render.locate): "¶3", " 3" and "03" are one paragraph
                para = str(int(str(r.get("paragraf", "")).strip().lstrip("¶").strip()))
            except ValueError:
                para = str(r.get("paragraf"))
            if r.get("tur") == "yenilik" and not e:
                if para in novelty_at:
                    e.append(f"{rid}: a second yenilik block after ¶{para} ({novelty_at[para]} is there); one per paragraph")
                else:
                    novelty_at[para] = rid
            seen.add(rid)
            if e:
                dropped.append({"id": rid, "errors": e})
                continue
            kept.append(r)
            per_para[para] = per_para.get(para, 0) + 1
            if TABAN.search(r.get("metin", "")) and not TABAN_OK.search(r.get("metin", "")):
                warnings.append(f"{rid}: metin calls the commentary 'taban'; say 'şerh' or state the point")
            if r.get("tur") == "yenilik" and r.get("tarama") == "dilim" and r.get("klasik_tanik") == "bulunamadi" \
                    and not any(w in r.get("metin", "").lower() for w in ("dilim", "yalnız", "sadece", "only")):
                warnings.append(f"{rid}: bulunamadi on the slice should say only the slice was searched")
        warnings += [f"¶{p}: {n} blocks after one paragraph (at most five)" for p, n in per_para.items() if n > 5]
        return kept, dropped, warnings


def validate(s: int, target: str, recs: list[dict], out: Path | None, gelenek: str = "ehlikitap") -> dict:
    kept, dropped, warnings = check_records(s, target, recs, gelenek)
    page_errors = []
    name, base, _ = R.target_page(s, target)
    if out and (out / name).exists():
        page_errors = check_page(out / name, base, kept)
    return {"surah": s, "target": target, "records": len(recs), "kept": len(kept), "dropped": dropped,
            "by_tur": dict(Counter(r.get("tur") for r in kept)), "by_kat": dict(Counter(r.get("kat") for r in kept)),
            "words": sum(B.words(r.get("metin", "")) for r in kept), "page_errors": page_errors,
            "warnings": warnings, "passed": not dropped and not page_errors}

FIELDS = SCHEMA["fields"]
REQUIRED = SCHEMA["block"]["required"]
LIMITS = SCHEMA["block"]["word_limits"]
KOD = {k: v["kod"] for k, v in ENUMS["tur"].items()}
PLACEMENT = ("paragraf", "capa")
ORDER = ["id", "gelenek", "tur", "ayet", "islev", "iliski", "durum", "kat", "guc", "klasik_tanik", "tarama", "taranan", "derece",
         "derece_veren", "tarihsellik", "kiraat_turu", "nusha", "tarihleme", "bag", "sozluk", "mutercim", "terim", "kayip", "yon", "kiyas", "taban",
         "hata", "alim", "ravi", "koken", "tekrar", "gerekce", "not", "metin", "kaynak"]
MODERN_DICT = {"VASIT", "MUHIT", "HANSWEHR"}
SHARED_KINDS = {"quran", "modern", "reference"}  # citable from every gelenek
MULTI = {"kayip", "nusha"}  # enum fields that take several pipe-separated values
AYET = re.compile(r"(\d+):(\d+)(?:-(\d+))?")
LOC = re.compile(r"^([A-Z][A-Z0-9-]*)(?::(.+))?$")


def words(text: str) -> int:
    return len(re.findall(r"\S+", text or ""))


class Corpus:
    """Read-only view of the Bible corpus index for source resolution."""

    def __init__(self, index: Path):
        if not Path(index).exists():
            raise SystemExit(f"corpus index {index} missing: run enrichment/bible/corpus.py build")
        self.con = sqlite3.connect(f"file:{index}?mode=ro", uri=True)  # read-only: never creates an empty index
        self.meta = {r[0]: json.loads(r[1]) for r in self.con.execute("SELECT id, meta FROM src")}

    def close(self):
        self.con.close()

    def resolve(self, loc: str) -> tuple[bool, str, dict]:
        """(ok, message, info). info: kind, access, sahih (hadith)."""
        m = LOC.match(loc)
        if not m:
            return False, f"malformed locator {loc!r}", {}
        sid, rest = m.group(1), m.group(2)
        meta = self.meta.get(sid)
        if not meta:
            return False, f"unknown source {sid!r}", {}
        info = {"kind": meta.get("kind"), "access": meta.get("access"), "id": sid, "gelenek": meta.get("gelenek")}
        if meta.get("access") == "hafiza":
            return True, "pointer (memory)", info
        if rest is None:
            return False, f"{loc}: locator needs a position (e.g. {sid}:107:3)", info
        # exact, else the first sub-segment (loc#2 …); two index lookups (an `OR … LIKE` scans the whole table:
        # 0.2 s per locator warm, minutes on a cold disk, which once cost a 1:1 page a full cache rewrite)
        row = (self.con.execute("SELECT extra FROM seg WHERE seg=?", (loc,)).fetchone()
               or self.con.execute("SELECT extra FROM seg WHERE seg>=? AND seg<? LIMIT 1", (loc + "#", loc + "$")).fetchone())
        if not row:
            return False, f"{loc}: no such segment", info
        extra = json.loads(row[0] or "{}")
        for key in ('gelenek', 'nusha', 'background_only', 'translation_aid', 'requires_original'):
            if key in extra:
                info[key] = extra[key]
        if "sahih" in extra:
            info["sahih"] = bool(extra["sahih"])
            info["graded_by"] = extra.get("graded_by") or []
        return True, "ok", info


def ayah_refs(ayet: str) -> list[tuple[int, int, int]]:
    out = []
    for part in ayet.split("|"):
        m = AYET.fullmatch(part.strip())
        if not m:
            raise ValueError(part)
        s, a = int(m.group(1)), int(m.group(2))
        out.append((s, a, int(m.group(3) or a)))
    return out


def check_record(r: dict, surah: int, n_ayat: int, corpus: Corpus | None, base_text: str = "") -> list[str]:
    """Every rule of schema.json that can be checked mechanically. Returns error strings."""
    e = []
    rid = r.get("id", "?")
    for k in REQUIRED:
        if not str(r.get(k, "")).strip():
            e.append(f"{rid}: missing {k}")
    for k, v in r.items():
        if k in PLACEMENT:
            continue
        if k not in FIELDS:
            e.append(f"{rid}: unknown field {k}")
            continue
        enum = FIELDS[k].get("enum")
        if enum:
            vals = str(v).split("|") if k in MULTI else [str(v)]
            for x in vals:
                if x not in ENUMS[enum]:
                    e.append(f"{rid}: {k}={x!r} not in {sorted(ENUMS[enum])}")
    tur, gel = r.get("tur"), r.get("gelenek")
    if tur in ENUMS["tur"] and gel in ENUMS["gelenek"] and gel not in ENUMS["tur"][tur]["gelenek"]:
        e.append(f"{rid}: tur {tur} is not used in gelenek {gel}")
    for k, f in FIELDS.items():
        req = f.get("required_for") or {}
        if tur in req.get("tur", []) or r.get("islev") in req.get("islev", []) or gel in req.get("gelenek", []):
            if not str(r.get(k, "")).strip():
                e.append(f"{rid}: {k} is required for {tur}/{r.get('islev')}")
    m = re.fullmatch(r"S(\d{3})-(?:(TEV|INC)-)?([A-Z]{3})-(\d{3})", rid)
    if not m:
        e.append(f"{rid}: id must be S<sss>-<KOD>-<NNN> (Islamic) or S<sss>-<TEV|INC>-<KOD>-<NNN> (Bible)")
    else:
        if int(m.group(1)) != surah:
            e.append(f"{rid}: id surah != {surah}")
        expected = {'tevrat': 'TEV', 'incil': 'INC', 'islami': None}.get(gel)
        if m.group(2) != expected:
            e.append(f"{rid}: id tradition prefix must be {expected or 'absent'} for {gel}")
        if tur in KOD and m.group(3) != KOD[tur]:
            e.append(f"{rid}: id code {m.group(3)} != {KOD[tur]} for tur {tur}")
    try:
        for s, a, b in ayah_refs(r.get("ayet", "")):
            if s != surah or a < 1 or b < a or b > n_ayat:
                e.append(f"{rid}: ayet {s}:{a}-{b} outside S{surah} (1-{n_ayat})")
    except ValueError as x:
        e.append(f"{rid}: malformed ayet {x}")
    limit = LIMITS.get(r.get("kat"), 80)
    if words(r.get("metin", "")) > limit:
        e.append(f"{rid}: metin {words(r.get('metin', ''))} words > {limit} for kat {r.get('kat')}")
    if "\n" in r.get("metin", ""):
        e.append(f"{rid}: metin must be one paragraph")
    # rules
    locs = [x.strip() for x in str(r.get("kaynak", "")).split("|") if x.strip()]
    memory = "hafiza" in locs
    infos = []
    if corpus:
        for loc in locs:
            if loc == "hafiza":
                continue
            ok, msg, info = corpus.resolve(loc)
            if not ok:
                e.append(f"{rid}: kaynak {msg}")
            else:
                infos.append(info)
                memory |= info.get("access") == "hafiza"
                if gel == "islami" and info.get("kind") == "intertext":
                    e.append(f"{rid}: {loc} is a Bible/Jewish/Christian source; it belongs to the separate pass")
                if info.get('background_only'):
                    if tur not in ('modern', 'kaynak_notu', 'yontem'):
                        e.append(f"{rid}: {loc} is background material; use modern/kaynak_notu/yontem, not a scripture link")
                elif gel in ("tevrat", "incil") and info.get("kind") not in SHARED_KINDS \
                        and gel not in (info.get("gelenek") or []):
                    e.append(f"{rid}: {loc} is not a source of gelenek {gel}")
                if info["id"] in MODERN_DICT and tur != "anlam_tarihi":
                    e.append(f"{rid}: modern dictionary {info['id']} only inside anlam_tarihi")
    if gel in ('tevrat', 'incil'):
        local = [info for info in infos if info.get('kind') == 'intertext' and info.get('access') != 'hafiza'
                 and not info.get('background_only')]
        originals = [info for info in local if not info.get('translation_aid')]
        if tur in ('paralel', 'motif', 'karsi_anlati', 'soydas', 'yorum_gelenegi') \
                and any(info.get('requires_original') for info in local) and not originals:
            e.append(f'{rid}: KJV is a finding aid; cite the Hebrew or Greek witness too')
        if originals and not memory:
            supported = {w for info in local for w in info.get('nusha', [])}
            claimed = set(str(r.get('nusha', '')).split('|'))
            if supported and not claimed <= supported:
                e.append(f'{rid}: nusha is not supported by the cited witnesses: {sorted(claimed-supported)}')
    if memory:
        if r.get("durum") != "degerlendirilmedi":
            e.append(f"{rid}: memory source requires durum:degerlendirilmedi")
        if tur in ("hadis", "nuzul"):
            e.append(f"{rid}: memory is not allowed for {tur}")
        if r.get("derece") and r.get("derece") != "degerlendirilmedi":
            e.append(f"{rid}: a grade cannot rest on memory")
    if tur == "hadis":
        if r.get("derece") != "sahih":
            e.append(f"{rid}: hadis accepts only derece:sahih")
        for info in infos:
            if info.get("kind") == "hadith" and info.get("sahih") is not True:  # ungraded (Ibn Hibban, Musnad) fails too
                e.append(f"{rid}: {info['id']} report is not sahih under the project rule"
                         + (" (the collection carries no grade)" if "sahih" not in info else ""))
    if tur == "esbab" and r.get("derece") not in (None, "", "degerlendirilmedi") and not r.get("derece_veren"):
        e.append(f"{rid}: derece_veren required when a grade is given")
    if tur == "duzeltme" and base_text and r.get("taban") and r["taban"] not in base_text:
        e.append(f"{rid}: taban not found verbatim in the base")
    if r.get("bag") in ("muhatap", "etki_iddiasi") and not r.get("alim"):
        e.append(f"{rid}: bag {r['bag']} must name the scholar who argues it (alim)")
    if r.get("bag") == "etki_iddiasi" and r.get("tarihleme") == "kuran_sonrasi":
        e.append(f"{rid}: a text dated after the Qur'an cannot carry etki_iddiasi")
    if r.get("islev") == "fazilet" and tur != "hadis":
        e.append(f"{rid}: merit reports are hadith: tur:hadis, sahih only (not {tur})")

